{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "Bumetanide, a close loop-diuretic analogue sharing the sulfamoylbenzoic acid core, showed absolute oral bioavailability of 0.79 ± 0.12 in elderly subjects, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Tolfenamic acid, an anthranilic acid derivative with moderate structural similarity, had absolute oral bioavailability of 61.6% in healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Hydrochlorothiazide, a sulfonamide diuretic, has absolute oral bioavailability of approximately 60–70% in humans, supporting high F for this sulfonamide-containing carboxylic acid.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Salicylate, a small carboxylic acid drug, showed complete absolute bioavailability after oral administration, supporting generally high oral absorption for this acidic drug class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C46"],
      "claim": "Azosemide, a structurally related furosemide analogue, has low oral bioavailability of 10–19% attributed to high first-pass metabolism; this is contradictory evidence but less transferable because azosemide contains a tetrazole acid bioisostere and a different metabolic profile.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is furosemide. Multiple structurally related loop diuretics and sulfonamide/anthranilic acid drugs show oral bioavailability well above the 20% threshold, while the closest low-bioavailability analogue (azosemide) differs in acid group and metabolic fate. The fed state may slow absorption but is unlikely to reduce furosemide's extent of absorption below 20%. Overall, high F is better supported.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for furosemide parent in the fed state is present in the evidence set.",
    "The highest-similarity record (C05) measures furosemide acyl glucuronide metabolite bioavailability, not parent furosemide, so it is not directly applicable.",
    "Azosemide's low bioavailability is informative but its tetrazole-for-carboxylate substitution and extensive first-pass metabolism limit transferability to furosemide."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

